class Solution {
  public int countBinarySubstrings(String s) {
    int n = 0, pre = 0, curr = 1;
    for (int i = 0; i < s.length() - 1; i++) {
      if (s.charAt(i) == s.charAt(i + 1)) {
        curr++;
      } else {
        pre = curr;
        curr = 1;
      }
      if (pre >= curr) {
        n++;
      }
    }
    return n;
  }
}

class Solution:
    def countBinarySubstrings(self, s: str) -> int:
        n = pre = 0
        curr = 1
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                curr += 1
            else:
                pre = curr
                curr = 1
            if pre >= curr:
                n += 1
        return n

const countBinarySubstrings = (s: string): number => {
  let n = 0;
  let pre = 0;
  let curr = 1;
  for (let i = 0; i < s.length - 1; i++) {
    if (s[i] === s[i + 1]) {
      curr++;
    } else {
      pre = curr;
      curr = 1;
    }
    if (pre >= curr) n++;
  }
  return n;
};
